use tokio::time::{self, Duration};
use tokio_test::{assert_pending, task};
use tokio_util::time::DelayQueue;

#[tokio::test]
async fn remove_last_item_wakes() {
    time::pause();
    let mut queue = task::spawn(DelayQueue::new());
    let key = queue.insert("foo", Duration::from_secs(100));
    assert_pending!(queue.enter(|cx, mut queue| queue.poll_expired(cx)));
    assert!(!queue.is_woken());
    queue.remove(&key);
    assert!(queue.is_empty());
    assert!(queue.is_woken(), "last removal left poll_expired asleep");
}

#[tokio::test]
async fn try_remove_last_item_wakes() {
    time::pause();
    let mut queue = task::spawn(DelayQueue::new());
    let key = queue.insert("foo", Duration::from_secs(100));
    assert_pending!(queue.enter(|cx, mut queue| queue.poll_expired(cx)));
    assert!(!queue.is_woken());
    queue.try_remove(&key).unwrap();
    assert!(queue.is_empty());
    assert!(queue.is_woken(), "last try_remove left poll_expired asleep");
}
