use std::{future, sync::{Arc, Mutex}, time::Duration};
use tokio::time;
use tokio_util::time::DelayQueue;

#[tokio::main]
async fn main() {
    for try_remove in [false, true] {
        let mut queue = DelayQueue::new();
        let key = queue.insert("foo", Duration::from_secs(100));
        let queue1 = Arc::new(Mutex::new(queue));
        let queue2 = queue1.clone();
        let h0 = tokio::spawn(async move {
            future::poll_fn(|cx| queue1.lock().unwrap().poll_expired(cx)).await
        });
        let h1 = tokio::spawn(async move {
            time::sleep(Duration::from_millis(100)).await;
            let mut queue = queue2.lock().unwrap();
            if try_remove {
                assert_eq!(queue.try_remove(&key).unwrap().into_inner(), "foo");
            } else {
                assert_eq!(queue.remove(&key).into_inner(), "foo");
            }
        });
        let result = time::timeout(Duration::from_millis(500), h0)
            .await.expect("task timed out").expect("task panicked");
        assert!(result.is_none());
        h1.await.expect("task panicked");
    }
    println!("Concurrent remove and try_remove both complete within 500ms");
}
RS
